<script setup lang="ts">
import type { GenerationRun } from '~/types/generation'
import { runLabels, moderationLabel, failureMessage } from '~/utils/generation'
defineProps<{ run: GenerationRun; pending?: boolean; readError?: string; pauseReason?: string }>()
defineEmits<{ refresh: [] }>()
</script>
<template><section class="generation-state" :class="`generation-state--${run.status}`" aria-labelledby="run-heading"><div class="generation-indicator"><div v-if="run.status === 'queued' || run.status === 'running'" class="generation-ring"><img src="/icons/fe006/progress-ring.svg" alt="" width="96" height="96"><strong>{{ run.status === 'queued' ? '…' : 'ИИ' }}</strong></div><div v-else class="generation-result-mark">{{ run.status === 'completed' ? '✓' : '!' }}</div><div><UiBadge :tone="run.status === 'completed' ? 'success' : run.status === 'failed' || run.status === 'timed_out' ? 'warning' : 'neutral'">{{ run.status }}</UiBadge><h2 id="run-heading" aria-live="polite">{{ runLabels[run.status] }}</h2><p v-if="run.status === 'queued'" class="muted">Запрос принят в очередь. Выполнение ещё не началось.</p><p v-else-if="run.status === 'running'" class="muted">Backend выполняет задачу. Подробные внутренние этапы и процент готовности API не сообщает.</p></div></div><div v-if="run.status === 'running'" class="generation-progress" role="progressbar" aria-label="Генерация без известного процента"><span /></div><div v-if="['queued', 'running'].includes(run.status)" class="generation-phases"><div><img src="/icons/fe006/check.svg" alt="" width="18" height="18"><span>Запрос сохранён и задача принята</span></div><div><img :src="run.status === 'running' ? '/icons/fe006/loader.svg' : '/icons/fe006/circle.svg'" :class="{ 'generation-spin': run.status === 'running' }" alt="" width="18" height="18"><span>{{ run.status === 'running' ? 'Генерация выполняется' : 'Ожидание выполнения' }}</span></div><div><img src="/icons/fe006/circle.svg" alt="" width="18" height="18"><span>Получение готового сценария</span></div></div><template v-else-if="run.status === 'completed'"><p>Сценарий готов к оценке педагогом. Завершение генерации не означает подтверждение фактов или согласование материала.</p><p v-if="run.moderation_status">{{ moderationLabel(run.moderation_status) }}</p><NuxtLink v-if="run.scenario_id" :to="{ path: `/scenarios/${run.scenario_id}`, query: { run: run.id } }" class="ui-button ui-button--primary">Открыть сценарий</NuxtLink><UiAlert v-else tone="warning">Сервер завершил задачу, но не передал ID сценария. Повторите чтение состояния.</UiAlert><NuxtLink to="/events">Перейти к моим мероприятиям</NuxtLink></template><template v-else><p>{{ failureMessage(run) }}</p><details v-if="run.error_message"><summary>Подробности ответа сервера</summary><p>{{ run.error_message }}</p></details><p v-if="run.error_code" class="muted">Код: {{ run.error_code }}</p><NuxtLink :to="{ path: `/scenario-requests/${run.scenario_request_id}`, query: { retry_run: run.id } }" class="ui-button ui-button--secondary">Проверить параметры и новую попытку</NuxtLink></template><UiAlert v-if="run.provider_name === 'mock'" tone="warning">Демонстрационная генерация: backend использует MockLlmProvider. Внешняя LLM не вызывалась.</UiAlert><UiAlert v-if="readError" tone="warning"><strong>Не удалось прочитать состояние</strong><p>{{ readError }}</p><p>Это ошибка связи при опросе, а не серверный статус failed. Новый POST не отправляется.</p></UiAlert><UiAlert v-if="pauseReason && pauseReason !== 'access'">{{ pauseReason === 'hidden' ? 'Опрос приостановлен в неактивной вкладке.' : pauseReason === 'local_limit' ? 'Локальное время наблюдения истекло. Серверная задача может продолжаться; timed_out не выставляется.' : 'Автоматический опрос приостановлен после ошибок связи.' }}</UiAlert><UiButton variant="secondary" :loading="pending" @click="$emit('refresh')">Обновить состояние</UiButton><p class="muted generation-id">ID запуска: {{ run.id }}</p></section></template>
